function teamStatsForGames(games){const items=teamRawStatsForGames(games);return state.teamMode==='game'&&games.length===1?teamStatsForView(games[0],items,detailStatsView(games[0])):items}
function opponentInfoMeta(game){if(!game)return '';const category=game.category||'未設定',rank=opponentRankForGame(game,state.opponentTeams)||'未設定';return `<div class="opponent-summary-meta"><span>対戦チームカテゴリー：${escapeHtml(category)}</span><span>対戦チームランク：${escapeHtml(rank)}</span></div>`}
