  const chooseExisting=(candidates,shotId=null)=>{
    modal(`<h2>${assist?'Madeシュートを選択':'既存ASTを選択'}</h2><p class="sub">同一Q・履歴上で近い順。関連付けを変更してもAST数は増えません。</p><div class="assist-editor-actions">${candidates.map(e=>`<button type="button" class="btn ghost" data-assist-event="${escapeHtml(e.eventId)}">${escapeHtml(assistPlayerLabel({number:e.playerNumber,name:e.playerName}))}<br>${escapeHtml(e.content)} ${e.shotAreaLabel?escapeHtml(e.shotAreaLabel):''}${e.assistEventId||e.shotEventId?'（関連付け済み・変更）':''}</button>`).join('')||'<p>候補がありません</p>'}</div><button class="btn ghost" id="assistEditorBack">戻る</button>`);quickModalClass('quick-sheet-modal',false);$('#assistEditorBack').onclick=back;let saving=false;
    document.querySelectorAll('[data-assist-event]').forEach(button=>button.onclick=async()=>{if(saving)return;saving=true;document.querySelectorAll('[data-assist-event]').forEach(b=>b.disabled=true);try{await saveAssistPlay(game,{kind:'link',shotEventId:assist?button.dataset.assistEvent:shotId,assistEventId:assist?current.eventId:button.dataset.assistEvent},current.quarter||1);done()}catch(error){toast(error.message);back()}});
  };
  const existingForShot=()=>{const index=items.findIndex(e=>e.eventId===current.eventId);return items.map((e,i)=>({e,d:Math.abs(i-index)})).filter(({e})=>isAssistEvent(e)&&Number(e.quarter||0)===Number(current.quarter||0)&&e.playerId!==current.playerId).sort((a,b)=>a.d-b.d).map(({e})=>e)};
